258  template <typename VAL=OpStr>
   259  struct TopDictOpSet : DictOpSet
   260  {
   261    static inline void process_op (OpCode op, InterpEnv<Number>& env, TopDictValues<VAL> & dictval)
   262    {
   263      switch (op) {
   264        case OpCode_CharStrings:
   265          dictval.charStringsOffset = env.argStack.pop_uint ();
   266          env.clear_args ();
   267          break;
   268        case OpCode_FDArray:
   269          dictval.FDArrayOffset = env.argStack.pop_uint ();
   270          env.clear_args ();
   271          break;
   272        case OpCode_FontMatrix:
   273          env.clear_args ();
   274          break;
   275        default:
   276          DictOpSet::process_op (op, env);
   277          break;
   278      }
   279    }
   280  };
