   282  template <typename OPSET, typename PARAM, typename ENV=NumInterpEnv>
   283  struct DictInterpreter : Interpreter<ENV>
   284  {
   285    inline bool interpret (PARAM& param)
   286    {
   287      param.init ();
   288      while (SUPER::env.substr.avail ())
   289      {
   290        OPSET::process_op (SUPER::env.fetch_op (), SUPER::env, param);
   291        if (unlikely (SUPER::env.in_error ()))
   292          return false;
   293      }
   294
   295      return true;
   296    }
   297
   298    private:
   299    typedef Interpreter<ENV> SUPER;
   300  };
